static int dpaa2_switch_add_vlan ( struct ethsw_port_priv * port_priv , u16 vid ) { struct ethsw_core * ethsw = port_priv -> ethsw_data ; struct dpsw_vlan_cfg vcfg = { 0 } ; int err ; vcfg . fdb_id = dpaa2_switch_port_get_fdb_id ( port_priv ) ; err = dpsw_vlan_add ( ethsw -> mc_io , 0 , ethsw -> dpsw_handle , vid , & vcfg ) ; if ( err ) { dev_err ( ethsw -> dev , "dpsw_vlan_add err %d\n" , err ) ; return err ; } return 0 ; } 